#!/usr/bin/env python3
"""P31-01: inventory model-load paths in this repo (generated; `--check` verifies the committed file is current)."""
import os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, ROOT)
from horizon.weights import intake as I
OUT = os.path.join(ROOT, "docs/evidence/p31/MODEL_LOAD_INVENTORY.md")
def render():
    inv = I.inventory(ROOT); L = ["# Model-load path inventory (generated by scripts/p31_inventory.py)", "", "Static pattern scan of `horizon/`, `bench/`, `scripts/` Python. It finds *literal* load calls only; dynamic imports, shell-outs and non-Python code are not covered.", "", "| Surface | Hits | Locations |", "|---|---|---|"]
    L += [f"| {k} | {len(v)} | {', '.join(v[:6]) or '—'} |" for k, v in inv.items()]
    L += ["", "Result: this repository contains **no model-loading code**: it never loads weights, adapters, tokenizers or inference images. The only hit is the `exec(` surface (sandboxed code execution, covered by P24-P27).",
          "HorizonWeights therefore guards the *admission decision* for an external protected runner; the runner's actual loader must call `horizon.weights.intake.admit()` and honour DENY. That integration cannot be verified from this repository.", "",
          "## Surfaces a deployment must still inventory by hand", "", "- inference server code and its own `from_pretrained`/`torch.load` calls", "- adapter hot-loading endpoints", "- tokenizer/chat-template downloads at start-up", "- container base images and entrypoints", "- mutable remote references (`latest`, branch names, unpinned tags)", "- serialization formats: pickle/torch zip, joblib, `.py` custom modeling code (`trust_remote_code`)"]
    return "\n".join(L) + "\n"
if __name__ == "__main__":
    t = render()
    if "--check" in sys.argv: sys.exit(0 if os.path.exists(OUT) and open(OUT).read() == t else (print("stale"), 1)[1])
    open(OUT, "w").write(t); print(t)
